/** Cascade behind `ProjectService.archiveProject`; returns the row count. */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

/** Live, still-open issues whose due date has passed. Drives the overdue job. */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          isNotNull(issues.dueAt),
          lt(issues.dueAt, now),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )
    .orderBy(issues.dueAt)
    .all();

  return rows.map((row) => toIssue(row));
}

/**
 * Private row → domain mappers for the repository layer.
 *
 * SQLite stores branded ids as plain text and collections as JSON strings, so
 * exactly one place is allowed to re-apply the brands and parse the JSON: here.
 * Services never see a `*Row` type.
 */
import type {
  ActivityEventRow,
  AttachmentRow,
  CommentRow,
  InvitationRow,
  InvoiceRow,
  IssueRow,
  LabelRow,
  MemberRow,
  NotificationPreferenceRow,
  NotificationRow,
  OrganizationRow,
  OrganizationUsageRow,
  ProjectRow,
  SubscriptionRow,
  UserRow,
} from "@/server/db";
import type {
  ActivityAction,
  ActivityEvent,
} from "@/types/activity";
import type { Invoice, Subscription } from "@/types/billing";
import type { Comment } from "@/types/comment";
import type {
  ActivityId,
  AttachmentId,
  CommentId,
  InvitationId,
  IsoTimestamp,
  IssueId,
  LabelId,
  MemberId,
  NotificationId,
  OrgId,
  ProjectId,
  SubscriptionId,
  UserId,
} from "@/types/common";
import type { Issue, IssueAttachment, IssueLabel } from "@/types/issue";
import type { Invitation, Member, User } from "@/types/member";
import type {
  Notification,
  NotificationChannel,
  NotificationPreference,
} from "@/types/notification";
import type {
  Organization,
  OrganizationUsage,
} from "@/types/organization";
