import { and, eq, inArray, isNull, notInArray } from \"drizzle-orm\";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from \"@/config/constants\";
import { newId } from \"@/lib/id\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { getDb, issues, milestones } from \"@/server/db\";
import { NotFoundError, requireFound } from \"@/server/services/_support\";
import { CLOSED_ISSUE_STATUSES } from \"@/types/issue\";
import type { IsoTimestamp, IssueId, MilestoneId, OrgId, ProjectId } from \"@/types/common\";
import type { Milestone, MilestoneProgress } from \"@/types/milestone\";
import type { CreateMilestoneInput, UpdateMilestoneInput } from \"@/schemas/milestone\";
import { toMilestone } from \"./_mappers\";
import { livePredicate, orgPredicate } from \"./base-repository\";

function scope(orgId: OrgId, milestoneId: MilestoneId) {
  return and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId));
}

export function findMilestoneById(orgId: OrgId, milestoneId: MilestoneId): Milestone | null {
  const row = getDb().select().from(milestones).where(scope(orgId, milestoneId)).get();
  return row ? toMilestone(row) : null;
}

export function requireOpenMilestone(orgId: OrgId, projectId: ProjectId, milestoneId: MilestoneId): Milestone {
  const milestone = findMilestoneById(orgId, milestoneId);
  if ("'!milestone || milestone.projectId !== projectId) throw new NotFoundError("Milestone", milestoneId);
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");
  return milestone;
}

export function listMilestones(orgId: OrgId, projectId: ProjectId): Milestone[] {
  return getDb().select().from(milestones)
    .where(and(orgPredicate(milestones.orgId, orgId), eq(milestones.projectId, projectId)))
    .all().map(toMilestone)
    .sort((a, b) => Number(a.closedAt !== null) - Number(b.closedAt !== null)
      || (a.targetDate === null ? (b.targetDate === null ? 0 : 1)
        : b.targetDate === null ? -1 : Date.parse(a.targetDate) - Date.parse(b.targetDate))
      || Date.parse(a.createdAt) - Date.parse(b.createdAt));
}

function assertCapacity(orgId: OrgId, projectId: ProjectId) {
  if (listMilestones(orgId, projectId).filter((m) => m.closedAt === null).length >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

function assertName(orgId: OrgId, projectId: ProjectId, name: string, except?: MilestoneId) {
  if (listMilestones(orgId, projectId).some((m) => m.id !== except && m.name.trim().toLowerCase() === name.trim().toLowerCase())) {
    throw new MilestoneStateError("name_taken");
  }
}

export function insertMilestone(input: CreateMilestoneInput, now: IsoTimestamp): Milestone {
  return getDb().transaction((tx) => {
    assertName(input.orgId, input.projectId, input.name);
    assertCapacity(input.orgId, input.projectId);
    return toMilestone(tx.insert(milestones).values({
      id: newId(), orgId: input.orgId, projectId: input.projectId,
      name: input.name, normalizedName: input.name.trim().toLowerCase(),
      targetDate: input.targetDate ?? null, closedAt: null, createdAt: now, updatedAt: now,
    }).returning().get());
  });
}

export function updateMilestone(input: UpdateMilestoneInput, now: IsoTimestamp): Milestone {
  return getDb().transaction((tx) => {
    const before = requireFound(findMilestoneById(input.orgId, input.milestoneId), "Milestone", input.milestoneId);
    if (input.name !== undefined) assertName(input.orgId, before.projectId, input.name, before.id);
    return toMilestone(tx.update(milestones).set({
      ...(input.name === undefined ? {} : { name: input.name, normalizedName: input.name.trim().toLowerCase() }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: now,
    }).where(scope(input.orgId, input.milestoneId)).returning().get());
  });
}

export function closeMilestone(orgId: OrgId, milestoneId: MilestoneId, targetId: MilestoneId | null, now: IsoTimestamp) {
  return getDb().transaction((tx) => {
    const before = requireFound(findMilestoneById(orgId, milestoneId), "Milestone", milestoneId);
    if (before.closedAt !== null) throw new MilestoneStateError("closed");
    if (targetId !== null) {
      if (targetId === milestoneId) throw new NotFoundError("Milestone", targetId);
      requireOpenMilestone(orgId, before.projectId, targetId);
    }
    const moved = tx.update(issues).set({ milestoneId: targetId, updatedAt: now })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, before.projectId),
        eq(issues.milestoneId, milestoneId), livePredicate(issues.archivedAt, {}),
        notInArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
      .returning({ id: issues.id }).all();
    const milestone = toMilestone(tx.update(milestones).set({ closedAt: now, updatedAt: now })
      .where(scope(orgId, milestoneId)).returning().get());
    return { milestone, movedIssueIds: moved.map((r) => r.id as IssueId) };
  });
}

export function reopenMilestone(orgId: OrgId, milestoneId: MilestoneId, now: IsoTimestamp): Milestone {
  return getDb().transaction((tx) => {
    const before = requireFound(findMilestoneById(orgId, milestoneId), "Milestone", milestoneId);
    if (before.closedAt === null) throw new MilestoneStateError("already_open");
    assertCapacity(orgId, before.projectId);
    return toMilestone(tx.update(milestones).set({ closedAt: null, updatedAt: now })
      .where(scope(orgId, milestoneId)).returning().get());
  });
}

export function getProgress(milestone: Milestone): MilestoneProgress {
  const rows = getDb().select({ status: issues.status }).from(issues)
    .where(and(orgPredicate(issues.orgId, milestone.orgId), eq(issues.projectId, milestone.projectId),
      eq(issues.milestoneId, milestone.id), livePredicate(issues.archivedAt, {}))).all();
  const closed = rows.filter((r) => CLOSED_ISSUE_STATUSES.includes(r.status)).length;
  return { total: rows.length, open: rows.length - closed, closed };
}
