    await expect(milestones.closeMilestone(tenant.actors.member, { orgId: tenant.org.id, milestoneId: source.id, moveOpenIssuesTo: closed.id }))
      .rejects.toMatchObject({ reason: "closed" });
    expect(events).toHaveLength(0);
    off();
    const created: unknown[] = [];
    const offCreate = subscribe("issue.created", (e) => { created.push(e); });
    await expect(issues.createIssue(tenant.actors.member, { ...issueInput(tenant.org.id, tenant.project.id), milestoneId: closed.id }))
      .rejects.toBeInstanceOf(MilestoneStateError);
    offCreate();
    expect(created).toHaveLength(0);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(0);
    expect((await milestones.getMilestone(tenant.actors.viewer, tenant.org.id, source.id)).milestone.closedAt).toBeNull();
