    const milestone = await create("Guarded");
    const issue = await issues.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id));
    const viewerOwns = { ...tenant.actors.member, role: "viewer" as const };
    expect((await issues.setIssueMilestone(viewerOwns, { orgId: tenant.org.id, issueId: issue.id, milestoneId: milestone.id })).milestoneId).toBe(milestone.id);
    await expect(milestones.updateMilestone(tenant.actors.viewer, { orgId: tenant.org.id, milestoneId: milestone.id, name: "Denied" }))
      .rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(milestones.listMilestones(tenant.actors.member, other.org.id, other.project.id)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(milestones.getMilestone(other.actors.member, other.org.id, milestone.id)).rejects.toBeInstanceOf(NotFoundError);
    await issueRepo.archiveIssue(tenant.org.id, issue.id);
    await expect(issues.setIssueMilestone(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, milestoneId: null }))
      .rejects.toBeInstanceOf(AlreadyArchivedError);
    await projectRepo.archiveProject(tenant.org.id, tenant.project.id);
    await expect(create("Archived")).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(milestones.updateMilestone(tenant.actors.member, { orgId: tenant.org.id, milestoneId: milestone.id, targetDate: null }))
      .rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await milestones.listMilestones(tenant.actors.viewer, tenant.org.id, tenant.project.id)).toHaveLength(1);
    expect(isDomainError(new MilestoneStateError("closed"))).toBe(true);
    expect(toAppError(new MilestoneStateError("closed")).code).toBe("conflict");
